DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.reserve_municipal_event(uuid)'::regprocedure) INTO def;def:=replace(def,'loc uuid;title text;','loc uuid;event_title text;');def:=replace(def,'title:=CASE','event_title:=CASE');def:=replace(def,'organization_events.title=title','organization_events.title=event_title');def:=replace(def,'VALUES(org,title,','VALUES(org,event_title,');EXECUTE def;END $$;